List<T> all=new(),want=new();HashSet<string> found=new();Dictionary<string,Image> hits=new();System.Random rng;Canvas cv;Font font;Sprite px;GameObject menu,game,over;Image room,dark;Text title,scoreT,timeT,targetT,hintT;int round,score,combo,hints;float time,last;bool run,cryptic;
