void Awake(){rng=new System.Random();Application.targetFrameRate=60;BuildData();BuildUI();ShowMenu();}
void Update(){if(!run)return;time-=Time.deltaTime*(1+Mathf.Max(0,round-8)*.04f);if(combo>0&&Time.time-last>3)combo=0;if(time<=0)End();Hud();}
