void BuildUI(){var g=new GameObject("Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));cv=g.GetComponent<Canvas>();cv.renderMode=RenderMode.ScreenSpaceOverlay;var s=g.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new(1280,720);if(FindFirstObjectByType<EventSystem>()==null)new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");px=Pixel();menu=Root("Menu");var bg=Img(menu.transform,Color.white);bg.sprite=Spr(Art(false));Stretch(bg.rectTransform);var shade=Img(menu.transform,new Color(0,0,0,.42f));Stretch(shade.rectTransform);var box=Panel(menu.transform,new(.10f,.14f),new(.52f,.86f));Txt(box.transform,"RELIC RUSH",60,gold,new(.06f,.70f),new(.94f,.93f));Txt(box.transform,"ENDLESS HIDDEN-OBJECT ROGUELITE",19,cream,new(.06f,.61f),new(.94f,.72f));Txt(box.transform,"Find objects, chain combos, survive harder rounds and chase your best score.",22,cream,new(.09f,.37f),new(.91f,.60f));Btn(box.transform,"START HUNT",new(.18f,.15f),new(.82f,.31f),StartRun,out _);
