void ShowMenu(){menu.SetActive(true);game.SetActive(false);over.SetActive(false);run=false;}void StartRun(){menu.SetActive(false);over.SetActive(false);game.SetActive(true);round=1;score=combo=0;hints=3;Begin();}
void Begin(){run=true;found.Clear();want.Clear();combo=0;cryptic=round>=3&&round%3==0;dark.gameObject.SetActive(round>=4&&round%4==0);bool tavern=round%2==0;room.sprite=Spr(Art(tavern));title.text=$"ROOM {round} — {(tavern?"SMUGGLER'S TAVERN":"ALCHEMIST WORKSHOP")}";int count=Mathf.Clamp(3+(round-1)/2,3,8);want.AddRange(all.OrderBy(x=>rng.Next()).Take(count));time=Mathf.Max(18,42-round)+2;MakeHits();Targets();Hud();}
