void Tap(T t){if(!run)return;if(want.Contains(t)&&!found.Contains(t.n)){found.Add(t.n);combo++;last=Time.time;score+=100+Mathf.Max(0,combo-1)*20;Targets();if(found.Count==want.Count){score+=Mathf.CeilToInt(time)*5;round++;Begin();}}else Wrong();}
void Wrong(){if(!run)return;combo=0;time=Mathf.Max(0,time-2.5f);}void Hint(){if(!run||hints<=0)return;var left=want.Where(t=>!found.Contains(t.n)).ToList();if(left.Count==0)return;hints--;var t=left[rng.Next(left.Count)];hits[t.n].color=new(1,.85f,.1f,.55f);Invoke(nameof(ClearHint),1);Hud();}void ClearHint(){foreach(var i in hits.Values)i.color=new(1,1,1,.001f);}
