GameObject Root(string n)=>Rect(n,cv.transform,Vector2.zero,Vector2.one).gameObject;RectTransform Rect(string n,Transform p,Vector2 a,Vector2 b){var g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;return r;}Sprite Pixel(){var t=new Texture2D(1,1);t.SetPixel(0,0,Color.white);t.Apply();return Spr(t);}Sprite Spr(Texture2D t)=>Sprite.Create(t,new Rect(0,0,t.width,t.height),new(.5f,.5f),100);Image Img(Transform p,Color c){var g=new GameObject("Image",typeof(RectTransform),typeof(Image));g.transform.SetParent(p,false);var i=g.GetComponent<Image>();i.sprite=px;i.color=c;return i;}GameObject Panel(Transform p,Vector2 a,Vector2 b){var o=Img(p,gold);o.rectTransform.anchorMin=a;o.rectTransform.anchorMax=b;o.rectTransform.offsetMin=o.rectTransform.offsetMax=Vector2.zero;var i=Img(o.transform,panel);Stretch(i.rectTransform);i.rectTransform.offsetMin=new(3,3);i.rectTransform.offsetMax=new(-3,-3);return i.gameObject;}Text Txt(Transform p,string v,int size,Color c,Vector2 a,Vector2 b){var g=new GameObject("Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;var t=g.GetComponent<Text>();t.font=font;t.text=v;t.fontSize=size;t.color=c;t.alignment=TextAnchor.MiddleCenter;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}Button Btn(Transform p,string label,Vector2 a,Vector2 b,Action act,out Text tx){var im=Img(p,green);im.rectTransform.anchorMin=a;im.rectTransform.anchorMax=b;im.rectTransform.offsetMin=im.rectTransform.offsetMax=Vector2.zero;var bt=im.gameObject.AddComponent<Button>();bt.onClick.AddListener(()=>act());tx=Txt(im.transform,label,19,cream,new(.03f,.05f),new(.97f,.95f));return bt;}static void Stretch(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=