Texture2D Art(bool tavern){const int W=320,H=180;var t=new Texture2D(W,H,TextureFormat.RGBA32,false);t.filterMode=FilterMode.Point;var p=new Color32[W*H];Color32 outl=new(19,14,18,255),stone=new(42,38,59,255),stone2=new(62,50,74,255),wood=new(91,53,31,255),wood2=new(125,72,38,255),g=new(211,151,47,255),pur=new(108,56,145,255),blu=new(46,96,131,255),gr=new(56,109,69,255),re=new(150,56,50,255),cr=new(220,198,150,255);for(int y=0;y<H;y++)for(int x=0;x<W;x++)p[y*W+x]=tavern?new Color32(46,31,31,255):stone;void R(int x,int y,int w,int h,Color32 c){for(int yy=Mathf.Max(0,y);yy<Mathf.Min(H,y+h);yy++)for(int xx=Mathf.Max(0,x);xx<Mathf.Min(W,x+w);xx++)p[yy*W+xx]=c;}void O(int x,int y,int w,int h,Color32 c){R(x-1,y-1,w+2,h+2,outl);R(x,y,w,h,c);}for(int y=0;y<120;y+=12)for(int x=(y/12%2)*8;x<W;x+=24){R(x,y,22,10,((x+y)/12)%2==0?stone:stone2);R(x,y+9,22,1,outl);}R(0,120,W,60,tavern?new Color32(68,40,27,255):new Color32(49,31,33,255));for(int x=0;x<W;x+=18)R(x,120,2,60,outl);O(125,15,70,48,new(25,43,62,255));R(129,19,62,40,new(42,75,99,255));R(159,19,3,40,outl);R(129,38,62,3,outl);for(int sy=64;sy<116;sy+=23){O(15,sy,115,5,wood2);O(205,sy,100,5,wood2);for(int i=0;i<9;i++){int x=22+i*11,h=8+i%4*3;O(x,sy-h,6,h,i%3==0?gr:i%3==1?pur:blu);O(212+i*10,sy-10-i%3*3,6,10+i%3*3,i%2==0?pur:g);}}O(68,128,186,34,wood);R(74,134,174,22,wood2);O(146,119,28,19,new(45,45,50,255));R(151,113,18,7,new(70,63,75,255));R(155,109,10,4,pur);O(28,48,13,5,g);O(89,82,13,11,cr);O(224,45,7,14,g);O(162,139,11,8,pur);O(249,94,6,18,cr);O(103,149,19,5,cr);O(270,141,16,4,new(164,168,177,255));O(69,143,7,7,g);O(52,108,12,10,re);O(287,86,8,12,g);O(141,100,8,7,g);O(187,97,18,11,new(52,45,41,255));O(10,86,10,18,g);O(233,149,9,8,re);O(275,31,18,12,g);for(int i=0;i<110;i++)R((i*47+13)%W,(i*29+7)%120,1,1,i%2==0?new Color32(88,76,98,255):new Color32(35,31,48,255));t.SetPixels32(p);t.Apply();return t;}
